/*
 * A094617  Triangular array T of numbers generated by these rules: 2 is in T;
 *          and if x is in T, then 2x-1 and 3x-2 are in T.
 * https://oeis.org/A094617
 *
 * Offset:    1    (a(1) is the first term)
 * Keywords:  nonn, tabl
 * Formula:   not stated
 * Range:     u8 n <= 25, u16 n <= 75, u32 n <= 250, u64 n <= 901,
 *            u128 n <= 3402, big any n
 * Helpers:   pow_int
 *
 * Sequence data from the OEIS (https://oeis.org), licensed CC BY-SA 4.0.
 */

/*  Sequence A094617:   a(n) = 1 + 2^i * 3^j
    where (i,j) are the unique exponents such that n lies on the
    (i+j)-th anti‑diagonal of the triangle generated by
        2 → 2x‑1 , 3x‑2.
    The algorithm finds the diagonal of index k = i + j,
    then the position within that diagonal, and evaluates 2^i·3^j+1.
    All arithmetic that may overflow a 64‑bit type is performed
    in 128‑bit integers.  For arbitrary‑precision seq_t the
    helper pow_int handles expansion automatically. */
#include <stdint.h>
#include <stddef.h>
#include "../utils/pow_int.h"

/* Return the nth term (offset 1) of A094617. */
seq_t a(idx_t n)
{
    /* Find k = i + j such that k(k+1)/2 ≥ n   and (k-1)k/2 < n.
       Use a doubling search followed by binary search. */
    idx_t low = 0, high = 1;
    /* Increase high until it satisfies the inequality. */
    while ((unsigned __int128)high * (high + 1) / 2 < n)
        high <<= 1;

    /* Binary search for the minimal high = k. */
    while (low + 1 < high) {
        idx_t mid = low + (high - low) / 2;
        if ((unsigned __int128)mid * (mid + 1) / 2 >= n)
            high = mid;
        else
            low = mid;
    }
    idx_t k = high;           /* k = i + j */
    idx_t s = k - 1;          /* diagonal index (0‑based) */

    /* Number of terms before this diagonal: (s+1)(s+2)/2 - (s+1) =
       s(s+1)/2. */
    idx_t prev = (unsigned __int128)s * (s + 1) / 2;

    /* Position within the diagonal (0‑based). */
    idx_t pos = n - prev - 1;
    /* i decreases from s to 0 as pos increases */
    idx_t i = s - pos;
    idx_t j = pos;

    /* Compute 2^i * 3^j + 1. */
    seq_t v2 = pow_int((seq_t)2, i);
    seq_t v3 = pow_int((seq_t)3, j);
    return 1 + v2 * v3;
}
